package com.rumitx.app.repeaters;
import android.app.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import android.widget.*;import android.view.*;
public abstract class FeatureActivity extends Activity implements LocationListener {
 protected Location position;protected android.location.LocationManager locations;protected boolean wantsLocation;protected Runnable afterStorage;protected TextView locationState;
 protected LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(16,16,16,16);l.setBackgroundColor(0xff050508);return l;}
 protected TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xffc5e9ef);t.setTextSize(size);t.setPadding(8,8,8,8);return t;}
 protected Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setMinHeight((int)(48*getResources().getDisplayMetrics().density));b.setOnClickListener(v->action.run());return b;}
 protected void message(String s){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
 protected void locationFeature(){wantsLocation=true;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED){startLocation();return;}new AlertDialog.Builder(this).setTitle("Location for repeaters").setMessage("RumiTX uses your location to show nearby repeaters, sort them by distance, and show your position on the offline map. Coordinates are processed on this phone. Voice and manual channels work without location.").setNegativeButton("Not now",(d,w)->unavailable()).setPositiveButton("Continue",(d,w)->requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},91)).show();}
 private void unavailable(){position=null;if(locationState!=null)locationState.setText("Location unavailable · browse or import normally. Tap Location to try again.");onPosition(null);}
 protected void startLocation(){locations=(android.location.LocationManager)getSystemService(LOCATION_SERVICE);if(locations==null){unavailable();return;}boolean active=false;for(String provider:new String[]{android.location.LocationManager.GPS_PROVIDER,android.location.LocationManager.NETWORK_PROVIDER})try{if(locations.isProviderEnabled(provider)){active=true;locations.requestLocationUpdates(provider,5000,10,this);Location cached=locations.getLastKnownLocation(provider);if(cached!=null&&System.currentTimeMillis()-cached.getTime()<600000&&(position==null||cached.getTime()>position.getTime()))onLocationChanged(cached);}}catch(SecurityException ignored){}catch(IllegalArgumentException ignored){}if(position==null&&locationState!=null)locationState.setText(active?"Waiting for location fix…":"Location providers disabled · enable GPS in phone settings.");}
 public void onLocationChanged(Location location){position=location;if(locationState!=null)locationState.setText(String.format(java.util.Locale.US,"Location %.5f, %.5f · ±%.0f m%s",location.getLatitude(),location.getLongitude(),location.getAccuracy(),System.currentTimeMillis()-location.getTime()>60000?" · cached":""));onPosition(location);}
 protected abstract void onPosition(Location p);
 public void onProviderEnabled(String p){if(wantsLocation)startLocation();}public void onProviderDisabled(String p){if(locationState!=null)locationState.setText("Location provider unavailable");}public void onStatusChanged(String p,int s,Bundle b){}
 protected void storage(Runnable action){if(checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED){action.run();return;}afterStorage=action;new AlertDialog.Builder(this).setTitle("USB files").setMessage("Allow file access to read your CSV exports from /sdcard/RumiTX/import and offline maps from /sdcard/RumiTX/maps.").setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,w)->requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE,Manifest.permission.WRITE_EXTERNAL_STORAGE},92)).show();}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==91){boolean granted=false;for(int r:results)if(r==PackageManager.PERMISSION_GRANTED)granted=true;if(granted)startLocation();else unavailable();}if(request==92){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&afterStorage!=null)afterStorage.run();else message("File access unavailable. You can still choose a CSV with the system file picker.");afterStorage=null;}}
 protected void onPause(){if(locations!=null)try{locations.removeUpdates(this);}catch(SecurityException ignored){}super.onPause();}
 protected void onResume(){super.onResume();if(wantsLocation&&(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED))startLocation();}
}
